// ─────────────────────────────────────────────
// FIX: lettura corretta del payload Telegram
// msg.payload.message contiene il messaggio completo
// ─────────────────────────────────────────────
const payload = msg.payload;
const tipo    = payload.type;
const chatId  = payload.chatId;

// ACCESSO CORRETTO: from e chat sono dentro payload.message
const message  = payload.message  || {};
const from     = message.from     || {};
const chat     = message.chat     || {};

const userId   = from.id;
const userName = from.username || from.first_name || String(userId);
const chatType = chat.type || "private";

// Salta tutto ciò che non è file/foto
if (tipo !== "photo" && tipo !== "document") {
    node.warn("FOTO_SKIP: tipo non file → " + tipo);
    return null;
}

node.warn(`FOTO_IN: type=${tipo} | chatType=${chatType} | userId=${userId} | chatId=${chatId}`);

// Estrai fileId corretto
let fileId;
if (tipo === "photo") {
    // content è un array di PhotoSize: prendi il più grande (ultimo)
    const photos = Array.isArray(payload.content) ? payload.content : [];
    fileId = photos.length > 0 ? photos[photos.length - 1].file_id : null;
} else if (tipo === "document") {
    fileId = payload.content && payload.content.file_id ? payload.content.file_id : null;
}

if (!fileId) {
    node.warn("FOTO_ERR: fileId non trovato");
    return null;
}

// Arricchisci msg con tutti i dati utili ai nodi successivi
msg.fileId   = fileId;
msg.userId   = userId;
msg.userName = userName;
msg.chatId   = chatId;
msg.chatType = chatType;
msg.tipo     = tipo;

node.warn(`BROADCAST_FOTO: fileId=${fileId} | userId=${userId} | chatId=${chatId}`);

return msg;

// Intercetta il comando /start (primo avvio bot)
const payload = msg.payload;
const tipo    = payload.type;
const content = payload.content || "";

// Solo messaggi di testo con /start
if (tipo !== "message") return null;
if (typeof content !== "string") return null;
if (!content.trim().startsWith("/start")) return null;

const message  = payload.message  || {};
const from     = message.from     || {};
const chat     = message.chat     || {};

msg.newUserId   = from.id;
msg.newUserName = from.username || from.first_name || String(from.id);
msg.newChatId   = payload.chatId;
msg.newChatType = chat.type || "private";

return msg;

// ─────────────────────────────────────────────
// CONFIGURA QUI
// ─────────────────────────────────────────────
const ADMIN_CHAT_ID = flow.get("ADMIN_CHAT_ID") || global.get("ADMIN_CHAT_ID") || 858001417;
// Sostituisci 858001417 con il tuo chatId admin oppure
// imposta la variabile di flow/globale ADMIN_CHAT_ID
// ─────────────────────────────────────────────

const userId   = msg.newUserId;
const userName = msg.newUserName;
const chatId   = msg.newChatId;

// Messaggio di benvenuto → all'utente
const welcomeMsg = {
    payload: {
        chatId: chatId,
        type:   "message",
        content: `👋 Benvenuto nel VIP Signals Bot, *${userName}*!\n\nUsa il menu qui sotto per iniziare.`,
        options: { parse_mode: "Markdown" }
    }
};

// Notifica admin → al tuo chatId
const adminMsg = {
    payload: {
        chatId: ADMIN_CHAT_ID,
        type:   "message",
        content: `🆕 *Nuovo utente attivato!*\n👤 Username: @${userName}\n🆔 UserId: ${userId}\n🕐 ${new Date().toLocaleString("it-IT")}`,
        options: { parse_mode: "Markdown" }
    }
};

// Output 1 → welcome all'utente
// Output 2 → notifica admin
return [ welcomeMsg, adminMsg ];
